    def evaluate(self, evaluation_metrics: Optional[List[str]] = None) -> Dict[str, Any]:
        metrics = evaluation_metrics if evaluation_metrics is not None else self.cfg.get("evaluation_metrics", [])
        results: Dict[str, Any] = {}
        adop = self.series.get("adoption_rate", [])
        if not adop:
            return results
        # Helper
        def time_to_threshold(th: float, window: int = 1) -> Optional[int]:
            if window <= 1:
                for i, v in enumerate(adop):
                    if v >= th: return i
                return None
            for i in range(len(adop) - window + 1):
                if all(v >= th for v in adop[i:i+window]): return i
            return None
        # Core metrics
        if "adoption_rate_over_time" in metrics:
            results["adoption_rate_over_time"] = adop
        if "time_to_50_percent_adoption" in metrics:
            results["time_to_50_percent_adoption"] = time_to_threshold(0.5, window=int(self.cfg.get("consistency_window", 1)))
        if "peak_adoption" in metrics:
            peak_val = max(adop); peak_day = adop.index(peak_val)
            results["peak_adoption"] = {"value": peak_val, "day": peak_day}
        if "sustained_adoption_duration" in metrics:
            thr = float(self.cfg.get("target_adoption_threshold", 0.7))
            best = cur = 0
            for v in adop:
                cur = cur + 1 if v >= thr else 0
                best = max(best, cur)
            results["sustained_adoption_duration"] = best
        if "subgroup_disparity_index" in metrics:
            # income top-bottom gap
            decs = self._precomputed_deciles or self._income_deciles()
            if len(decs) >= 2:
                bottom = decs[0]; top = decs[-1]
                b = sum(1.0 if self.people[i].current_mask_use else 0.0 for i in bottom)/len(bottom)
                t = sum(1.0 if self.people[i].current_mask_use else 0.0 for i in top)/len(top)
                results["subgroup_disparity_index"] = t - b
            else:
                results["subgroup_disparity_index"] = None
        if "policy_enforcement_events" in metrics:
            results["policy_enforcement_events"] = self.enforcement_actions
        if "mask_inventory_outage_days" in metrics:
            shares = self.series.get("retailer_stockout_share", [])
            results["mask_inventory_outage_days"] = sum(1 for s in shares if s > 0.0)
        if "masks_sold" in metrics:
            results["masks_sold"] = self.total_masks_sold
        if "campaign_cost_effectiveness" in metrics:
            # naive: adoption delta per spend unit
            spend = self.policy_cost_total if self.policy_cost_total > 0 else None
            results["campaign_cost_effectiveness"] = (adop[-1] - adop[0]) / spend if spend else None
        if self.with_epi and "effective_reproduction_number_Rt" in metrics:
            results["effective_reproduction_number_Rt"] = self.series.get("Rt_over_time", [])
        if self.with_epi and "infections_averted" in metrics:
            results["infections_averted"] = self.metrics.get("infections_averted", None)
        return results

